template<class T>std::vector<T>readvec(std::filesystem::path p){std::ifstream in(p,std::ios::binary);std::vector<char>b((std::istreambuf_iterator<char>(in)),{});std::vector<T>a(b.size()/sizeof(T));memcpy(a.data(),b.data(),b.size());return a;}
int main(int argc,char**argv){int rep=argc>1?atoi(argv[1]):3;auto dir=std::filesystem::path(__FILE__).parent_path();auto input=readvec<float>(dir/"fixture_bits.bin");auto gold=readvec<double>(dir/"expected_full_outputs.bin");int fx=input[0],fy=input[1],na=input[2],nc=input[3],nb=input[4],K=fx*fy*na,BL=K*7+17,OL=K*9+17,SL=K+17,LEN=1+BL+OL+SL;float*dc,*db,*dd,*da,*dh,*dout,*ds;int*count;auto alloc=[&](float**p,int n){cudaMalloc(p,n*4);};alloc(&dc,K*3);alloc(&db,BL);alloc(&dd,K*2);alloc(&da,24);alloc(&dh,3);alloc(&dout,OL);alloc(&ds,SL);cudaMalloc(&count,4);auto cls=input.data()+40;auto box=cls+K*3;auto dirs=box+BL;cudaMemcpy(dc,cls,K*3*4,cudaMemcpyHostToDevice);cudaMemcpy(dd,dirs,K*2*4,cudaMemcpyHostToDevice);cudaMemcpy(da,input.data()+10,24*4,cudaMemcpyHostToDevice);cudaMemcpy(dh,input.data()+34,3*4,cudaMemcpyHostToDevice);std::vector<float>blankO(OL,-12345.f),blankS(SL,-12345.f);auto reset=[&](){cudaMemcpy(db,box,BL*4,cudaMemcpyHostToDevice);cudaMemcpy(dout,blankO.data(),OL*4,cudaMemcpyHostToDevice);cudaMemcpy(ds,blankS.data(),SL*4,cudaMemcpyHostToDevice);cudaMemset(count,0,4);};auto execute=[&](float threshold){postprocess<<<fx*fy,na>>>(dc,db,dd,da,dh,dout,ds,count,input[5],input[6],input[7],input[8],fx,fy,na,nc,nb,threshold,input[9]);};for(int c=0;c<3;c++){reset();execute(input[37+c]);cudaDeviceSynchronize();}auto side=std::filesystem::path("/home/imo/HeCBench_julia/.porting-state/portable_julia/raw_sidecars/p4")/("cuda_"+std::to_string(getpid())+"_"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));std::filesystem::create_directories(side);for(int trial=1;trial<=5;trial++){std::vector<float>canonical,raw;double times[3]={0},ma=0,mr=0,se=0,total=0;int counts[3];bool ok=true;for(int c=0;c<3;c++){for(int z=0;z<rep;z++){reset();cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();execute(input[37+c]);cudaDeviceSynchronize();times[c]+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/rep;}total+=times[c];int n;cudaMemcpy(&n,count,4,cudaMemcpyDeviceToHost);if(n<0||n>K)return 2;counts[c]=n;std::vector<float>changed(BL),bnd(OL),score(SL);cudaMemcpy(changed.data(),db,BL*4,cudaMemcpyDeviceToHost);cudaMemcpy(bnd.data(),dout,OL*4,cudaMemcpyDeviceToHost);cudaMemcpy(score.data(),ds,SL*4,cudaMemcpyDeviceToHost);std::vector<float>rr;rr.push_back(n);rr.insert(rr.end(),changed.begin(),changed.end());rr.insert(rr.end(),bnd.begin(),bnd.end());rr.insert(rr.end(),score.begin(),score.end());raw.insert(raw.end(),rr.begin(),rr.end());auto got=rr;std::vector<int>order(n);std::iota(order.begin(),order.end(),0);std::sort(order.begin(),order.end(),[&](int a,int b){return bnd[a*9+8]<bnd[b*9+8];});int bs=1+BL,ss=bs+OL;for(int j=0;j<n;j++){int k=order[j];for(int f=0;f<9;f++)got[bs+j*9+f]=bnd[k*9+f];got[ss+j]=score[k];}const double*g=gold.data()+c*LEN;std::vector<bool>accept(K,false);int en=g[0];for(int j=0;j<en;j++)accept[int(g[bs+j*9+8])/7]=true;for(int i=0;i<LEN;i++){double err=fabs(double(got[i])-g[i]);ma=std::max(ma,err);mr=std::max(mr,err/std::max(fabs(g[i]),1e-12));bool strict=i==0||g[i]==-12345.;if(i>=1&&i<1+K*7)strict|=!accept[(i-1)/7];if(i>=bs&&i<ss)strict|=(i-bs)%9>=7;double tol=i>=ss?1e-6:1e-3;if(i>=ss&&g[i]!=-12345.)se=std::max(se,err);ok&=std::isfinite(got[i])&&(strict?double(got[i])==g[i]:err<=tol);}canonical.insert(canonical.end(),got.begin(),got.end());}ok&=cudaGetLastError()==cudaSuccess;auto artifact=input;artifact.insert(artifact.end(),canonical.begin(),canonical.end());std::string file=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/output_trial"+std::to_string(trial)+".bin";FILE*f=fopen(file.c_str(),"wb");fwrite(artifact.data(),4,artifact.size(),f);fclose(f);auto sf=(side/("raw_trial"+std::to_string(trial)+".bin")).string();f=fopen(sf.c_str(),"wb");fwrite(raw.data(),4,raw.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":%.17g,\"max_score_abs_error\":%.17g,\"timing_region\":\"sum3_independent_postprocess_kernels_only\",\"jit_excluded\":true,\"internal_repeats\":%d,\"per_path_times_seconds\":[%.17g,%.17g,%.17g],\"accepted_counts\":[%d,%d,%d],\"raw_output_sidecar\":\"%s\",\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,total,ok?"true":"false",canonical.size(),ma,mr,se,rep,times[0],times[1],times[2],counts[0],counts[1],counts[2],sf.c_str(),file.c_str(),artifact.size());}}
